SourceCode.Declaration:
class FMUpdateCustomerAction extends FMCustomerPage
{
    private str custEmail;
    private str driversLicense;

}

Method.Source:
[SysAppField(fieldStr(FMCustomer, DriverLicense), "Drivers license")]
public str driverLicenseNumber(str _value=driversLicense)
{
    driversLicense = _value;
    return driversLicense;
}

[SysAppField(fieldStr(FMCustomer, Email), "Email")]
public str customerEmail(str _value=custEmail)
{
    custEmail = _value;
    return custEmail;
}

public boolean validate(SysAppResponse _response)
{
    boolean validationPassed = true;

    if (this.driverLicenseNumber() == "")
    {
        _response.addMessage(new SysAppResponseMessage("Driver license number should be specified", SysAppMessageType::Error));
        validationPassed = false;
    }

    if (this.customerEmail() == "")
    {
        _response.addMessage(new SysAppResponseMessage("Customer email address should be specified", SysAppMessageType::Error));
        validationPassed = false;
    }

    return validationPassed;
}

public SysAppResponse updateCustomerDetails(SysAppEntityContext _entityContext, List _filterContextList)
{
    SysAppResponse response = new SysAppResponse();

    if (this.validate(response))
    {
        int64 recIdPassed = str2Int64(_entityContext.entityId());

        if (recIdPassed)
        {
            FMCustomer customer;
            ttsbegin;
            select firstonly forupdate * from customer
                where Customer.RecId == recIdPassed;

            if (customer.RecId)
            {
                customer.Email = this.customerEmail();
                customer.DriverLicense = this.driverLicenseNumber();
                customer.update();
            }

            ttscommit;

            response.addCommit(_entityContext);
        }
    }
    return response;
}
